!function(){"use strict";if(window.matchMedia("(prefers-reduced-motion: reduce)").matches)return void document.querySelectorAll(".animated-icon").forEach(e=>{e.classList.add("revealed")});const e=new IntersectionObserver(function(t){t.forEach(function(t){t.isIntersecting&&(t.target.classList.add("revealed"),e.unobserve(t.target))})},{threshold:.5});document.querySelectorAll(".animated-icon").forEach(function(t){e.observe(t)})}();